"""Voting and debate topology harness, stdlib only.

Runs star / chain / tree / graph topologies under a scripted task. Each
agent has a base-accuracy probability and an error_bias direction (which
wrong answer it drifts to on miss). We simulate N agents, rounds of
refinement, and measure (accuracy, tokens, simulated latency).
"""
from __future__ import annotations

import random
from dataclasses import dataclass, field


@dataclass
class SimAgent:
    name: str
    base_accuracy: float
    error_bias: str
    tokens_per_call: int = 400

    def answer(self, correct: str, rng: random.Random) -> str:
        return correct if rng.random() < self.base_accuracy else self.error_bias


@dataclass
class RunResult:
    topology: str
    n: int
    final_answer: str
    correct: str
    tokens: int
    steps: int

    def accuracy(self) -> int:
        return 1 if self.final_answer == self.correct else 0


def majority(items: list[str]) -> str:
    counts: dict[str, int] = {}
    for it in items:
        counts[it] = counts.get(it, 0) + 1
    return max(counts, key=counts.get)


def run_star(agents: list[SimAgent], correct: str, rng: random.Random) -> RunResult:
    hub = agents[0]
    workers = agents[1:]
    answers = [w.answer(correct, rng) for w in workers]
    tokens = sum(w.tokens_per_call for w in workers) + hub.tokens_per_call
    final = majority(answers) if answers else hub.answer(correct, rng)
    return RunResult("star", len(agents), final, correct, tokens, steps=2)


def run_chain(agents: list[SimAgent], correct: str, rng: random.Random) -> RunResult:
    current = agents[0].answer(correct, rng)
    tokens = agents[0].tokens_per_call
    for a in agents[1:]:
        proposal = a.answer(correct, rng)
        current = proposal if proposal != current and rng.random() < a.base_accuracy else current
        tokens += a.tokens_per_call
    return RunResult("chain", len(agents), current, correct, tokens, steps=len(agents))


def run_tree(agents: list[SimAgent], correct: str, rng: random.Random) -> RunResult:
    root = agents[0]
    leaves = agents[1:]
    if len(leaves) <= 1:
        return run_star(agents, correct, rng)
    mid = len(leaves) // 2
    left_answers = [a.answer(correct, rng) for a in leaves[:mid]]
    right_answers = [a.answer(correct, rng) for a in leaves[mid:]]
    tokens = sum(a.tokens_per_call for a in leaves) + root.tokens_per_call
    left_consensus = majority(left_answers)
    right_consensus = majority(right_answers)
    final = majority([left_consensus, right_consensus])
    return RunResult("tree", len(agents), final, correct, tokens, steps=3)


def run_graph(agents: list[SimAgent], correct: str, rng: random.Random, rounds: int = 2) -> RunResult:
    # Every agent proposes, then every agent sees all proposals and may update
    # (scaled down accuracy if they drift toward consensus).
    positions = [a.answer(correct, rng) for a in agents]
    tokens = sum(a.tokens_per_call for a in agents)
    for _ in range(rounds - 1):
        majority_now = majority(positions)
        new_positions = []
        for pos, ag in zip(positions, agents):
            if pos != majority_now and rng.random() < 0.4:
                new_positions.append(majority_now)
            else:
                new_positions.append(pos)
            tokens += ag.tokens_per_call
        positions = new_positions
    return RunResult("graph", len(agents), majority(positions), correct, tokens, steps=rounds * 2)


def make_agents(n: int, heterogeneous: bool, seed: int) -> list[SimAgent]:
    rng = random.Random(seed)
    if heterogeneous:
        biases = ["WRONG-A", "WRONG-B", "WRONG-C"]
        accuracies = [0.72, 0.70, 0.74, 0.71, 0.73, 0.70, 0.72]
    else:
        biases = ["WRONG-A"]
        accuracies = [0.72] * 7
    return [
        SimAgent(f"agent-{i}", accuracies[i % len(accuracies)], biases[i % len(biases)])
        for i in range(n)
    ]


def bench(correct: str, trials: int, heterogeneous: bool) -> None:
    tag = "HETEROGENEOUS" if heterogeneous else "HOMOGENEOUS (monoculture)"
    print("\n" + "=" * 72)
    print(f"BENCHMARK: {tag}")
    print("=" * 72)
    print(f"{'topology':10s} {'N':>3s} {'acc':>8s} {'avg_tokens':>12s} {'steps':>6s}")
    for topology in ("star", "chain", "tree", "graph"):
        for n in (3, 5, 7):
            acc_sum = 0
            tok_sum = 0
            step_sum = 0
            for t in range(trials):
                agents = make_agents(n, heterogeneous, seed=t)
                rng = random.Random(t * 31 + 7)
                if topology == "star":
                    r = run_star(agents, correct, rng)
                elif topology == "chain":
                    r = run_chain(agents, correct, rng)
                elif topology == "tree":
                    r = run_tree(agents, correct, rng)
                else:
                    r = run_graph(agents, correct, rng)
                acc_sum += r.accuracy()
                tok_sum += r.tokens
                step_sum += r.steps
            print(f"{topology:10s} {n:>3d} {acc_sum/trials:>8.2f} {tok_sum//trials:>12d} {step_sum//trials:>6d}")


def main() -> None:
    bench(correct="RIGHT", trials=200, heterogeneous=False)
    bench(correct="RIGHT", trials=200, heterogeneous=True)
    print("\nTakeaways:")
    print("  heterogeneous ensembles outperform homogeneous at every topology/N.")
    print("  graph/N=7 shows coordination tax: tokens inflate ~7x over star/N=3.")
    print("  star is the cost-sweet-spot for low-stakes aggregation.")
    print("  chain underperforms on monoculture because one bias propagates along the chain.")


if __name__ == "__main__":
    main()

// Lesson: Voting, Self-Consistency, and Debate Topology (phase 16 / lesson 15)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/16-multi-agent-and-swarms/15-voting-debate-topology/docs/en.md
// Run: npx tsx phases/16-multi-agent-and-swarms/15-voting-debate-topology/code/main.ts

export {};

class Random {
  private state: number;

  constructor(seed: number) {
    this.state = seed >>> 0;
  }

  random(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }
}

class SimAgent {
  constructor(
    public name: string,
    public baseAccuracy: number,
    public errorBias: string,
    public tokensPerCall = 400,
  ) {}

  answer(correct: string, rng: Random): string {
    return rng.random() < this.baseAccuracy ? correct : this.errorBias;
  }
}

class RunResult {
  constructor(
    public topology: string,
    public n: number,
    public finalAnswer: string,
    public correct: string,
    public tokens: number,
    public steps: number,
  ) {}

  accuracy(): number {
    return this.finalAnswer === this.correct ? 1 : 0;
  }
}

function majority(items: string[]): string {
  const counts = new Map<string, number>();
  for (const it of items) counts.set(it, (counts.get(it) ?? 0) + 1);
  let best = "";
  let bestVal = -1;
  for (const [k, v] of counts) {
    if (v > bestVal) {
      best = k;
      bestVal = v;
    }
  }
  return best;
}

function sumTokens(agents: SimAgent[]): number {
  return agents.reduce((s, a) => s + a.tokensPerCall, 0);
}

function runStar(agents: SimAgent[], correct: string, rng: Random): RunResult {
  const hub = agents[0];
  const workers = agents.slice(1);
  const answers = workers.map((w) => w.answer(correct, rng));
  const tokens = sumTokens(workers) + hub.tokensPerCall;
  const final = answers.length > 0 ? majority(answers) : hub.answer(correct, rng);
  return new RunResult("star", agents.length, final, correct, tokens, 2);
}

function runChain(agents: SimAgent[], correct: string, rng: Random): RunResult {
  let current = agents[0].answer(correct, rng);
  let tokens = agents[0].tokensPerCall;
  for (const a of agents.slice(1)) {
    const proposal = a.answer(correct, rng);
    current = proposal !== current && rng.random() < a.baseAccuracy ? proposal : current;
    tokens += a.tokensPerCall;
  }
  return new RunResult("chain", agents.length, current, correct, tokens, agents.length);
}

function runTree(agents: SimAgent[], correct: string, rng: Random): RunResult {
  const root = agents[0];
  const leaves = agents.slice(1);
  if (leaves.length <= 1) return runStar(agents, correct, rng);
  const mid = Math.floor(leaves.length / 2);
  const leftAnswers = leaves.slice(0, mid).map((a) => a.answer(correct, rng));
  const rightAnswers = leaves.slice(mid).map((a) => a.answer(correct, rng));
  const tokens = sumTokens(leaves) + root.tokensPerCall;
  const leftConsensus = majority(leftAnswers);
  const rightConsensus = majority(rightAnswers);
  const final = majority([leftConsensus, rightConsensus]);
  return new RunResult("tree", agents.length, final, correct, tokens, 3);
}

function runGraph(agents: SimAgent[], correct: string, rng: Random, rounds = 2): RunResult {
  let positions = agents.map((a) => a.answer(correct, rng));
  let tokens = sumTokens(agents);
  for (let r = 0; r < rounds - 1; r++) {
    const majorityNow = majority(positions);
    const newPositions: string[] = [];
    positions.forEach((pos, i) => {
      if (pos !== majorityNow && rng.random() < 0.4) {
        newPositions.push(majorityNow);
      } else {
        newPositions.push(pos);
      }
      tokens += agents[i].tokensPerCall;
    });
    positions = newPositions;
  }
  return new RunResult("graph", agents.length, majority(positions), correct, tokens, rounds * 2);
}

function makeAgents(n: number, heterogeneous: boolean, seed: number): SimAgent[] {
  void seed;
  let biases: string[];
  let accuracies: number[];
  if (heterogeneous) {
    biases = ["WRONG-A", "WRONG-B", "WRONG-C"];
    accuracies = [0.72, 0.70, 0.74, 0.71, 0.73, 0.70, 0.72];
  } else {
    biases = ["WRONG-A"];
    accuracies = new Array<number>(7).fill(0.72);
  }
  const out: SimAgent[] = [];
  for (let i = 0; i < n; i++) {
    out.push(new SimAgent(`agent-${i}`, accuracies[i % accuracies.length], biases[i % biases.length]));
  }
  return out;
}

function bench(correct: string, trials: number, heterogeneous: boolean): void {
  const tag = heterogeneous ? "HETEROGENEOUS" : "HOMOGENEOUS (monoculture)";
  console.log("\n" + "=".repeat(72));
  console.log(`BENCHMARK: ${tag}`);
  console.log("=".repeat(72));
  console.log(`${"topology".padEnd(10)} ${"N".padStart(3)} ${"acc".padStart(8)} ${"avg_tokens".padStart(12)} ${"steps".padStart(6)}`);
  for (const topology of ["star", "chain", "tree", "graph"]) {
    for (const n of [3, 5, 7]) {
      let accSum = 0;
      let tokSum = 0;
      let stepSum = 0;
      for (let t = 0; t < trials; t++) {
        const agents = makeAgents(n, heterogeneous, t);
        const rng = new Random(t * 31 + 7);
        let r: RunResult;
        if (topology === "star") {
          r = runStar(agents, correct, rng);
        } else if (topology === "chain") {
          r = runChain(agents, correct, rng);
        } else if (topology === "tree") {
          r = runTree(agents, correct, rng);
        } else {
          r = runGraph(agents, correct, rng);
        }
        accSum += r.accuracy();
        tokSum += r.tokens;
        stepSum += r.steps;
      }
      const acc = (accSum / trials).toFixed(2).padStart(8);
      const tok = String(Math.floor(tokSum / trials)).padStart(12);
      const steps = String(Math.floor(stepSum / trials)).padStart(6);
      console.log(`${topology.padEnd(10)} ${String(n).padStart(3)} ${acc} ${tok} ${steps}`);
    }
  }
}

function main(): void {
  bench("RIGHT", 200, false);
  bench("RIGHT", 200, true);
  console.log("\nTakeaways:");
  console.log("  heterogeneous ensembles outperform homogeneous at every topology/N.");
  console.log("  graph/N=7 shows coordination tax: tokens inflate ~7x over star/N=3.");
  console.log("  star is the cost-sweet-spot for low-stakes aggregation.");
  console.log("  chain underperforms on monoculture because one bias propagates along the chain.");
}

main();
